func sovTenants(x uint64) (n int) {
	return (math_bits.Len64(x|1) + 6) / 7
}
func sozTenants(x uint64) (n int) {
	return sovTenants(uint64((x << 1) ^ uint64((int64(x) >> 63))))
}
